<style scoped lang="scss" src="./d-element-library.scss"></style>

<script>
import { Component, Prop, Vue, Watch } from "vue-property-decorator";
import Button from "../button/button";
import { ButtonMode } from "../button/button.constants";
import { IconShape } from "../icon/icon.constants";
import DElementLibraryPage from "./d-element-library-page/d-element-library-page";
import Scroll from "../scroll/scroll.vue";

@Component({
  components: {
    Button,
    DElementLibraryPage,
    Scroll,
  },
})
export default class DElementLibrary extends Vue {
  @Prop({
    type: Array,
    default: () => [],
  })
  pages;

  @Prop({
    type: String,
  })
  initialPage;

  pageStack = [];
  back = false;
  contentHeight = 0;

  get ButtonMode() {
    return ButtonMode;
  }

  get IconShape() {
    return IconShape;
  }

  get currentPageKey() {
    return this.pageStack[this.pageStack.length - 1];
  }

  get title() {
    return (
      this.pages.find((page) => page.key === this.currentPageKey)?.title ||
      "Element Library"
    );
  }

  @Watch("pageStack", { deep: true })
  onPageChanged() {
    this.$emit("pageChanged", this.currentPageKey);
  }

  /**
   * This is a hack to figure out initial content height.
   *
   * beforeMount is called to set the pageStack to [-1] <--arbitrary start value,
   * mounted() is then called afterwards to reset the pageStack,
   * which fires the `<transition-group />` `@enter` event
   */
  beforeMount() {
    if (!this.initialPage) {
      this.pageStack = [-1];
    }
  }

  mounted() {
    if (!this.initialPage) {
      this.goHome();
    } else {
      this.goTo(this.initialPage);
    }
  }

  goTo(page) {
    this.back = false;
    this.pageStack.push(page);
  }

  goBack() {
    if (this.pageStack.length > 0) {
      this.back = true;
      this.pageStack.pop();
    }
  }

  goHome() {
    this.back = true;
    this.pageStack = [];
  }

  handleEnter(el) {
    const newHeight = getComputedStyle(el).height;
    this.contentHeight = newHeight;
  }

  resetHeight() {
    const previous = this.pageStack.slice();

    this.pageStack = [-1];

    requestAnimationFrame(() => {
      this.pageStack = previous;
    });
  }
}
</script>

<template>
  <div class="DElementLibrary">
    <!-- Header -->
    <div class="DElementLibrary__HeaderContainer">
      <div class="DElementLibrary__HeaderLeft">
        <Button
          v-if="pageStack.length"
          class="DElementLibrary__Icon"
          :icon="IconShape.LEFT"
          :iconColor="'white'"
          :mode="ButtonMode.ICON"
          @click="goBack"
        />
      </div>
      <div class="DElementLibrary__HeaderCenter">
        <h2 class="DElementLibrary__HeaderTitle">
          {{ title }}
        </h2>
      </div>
      <div class="DElementLibrary__HeaderRight"></div>
    </div>

    <!-- Content -->
    <div class="DElementLibrary__Content" :style="{ height: contentHeight }">
      <Scroll
        :options="{
          scrollPanel: {
            scrollingX: false,
          },
        }"
      >
        <transition-group
          class="div-slider"
          tag="div"
          :name="back ? 'slideback' : 'slide'"
          @enter="handleEnter"
        >
          <!-- hack to figure out initial content height -->
          <div v-if="pageStack[0] === -1" key="hack"></div>
          <!-- if no pages clicked on, show default element library page -->
          <div v-else-if="pageStack.length === 0" key="default">
            <slot
              :goTo="goTo"
              :goBack="goBack"
              :goHome="goHome"
              :resetHeight="resetHeight"
            />
          </div>
          <!-- else, show the selected page -->
          <div v-else :key="currentPageKey">
            <slot
              :name="currentPageKey"
              :goTo="goTo"
              :goBack="goBack"
              :goHome="goHome"
              :resetHeight="resetHeight"
            >
              <!-- Fallback content, in case the page doesn't exist -->
              <DElementLibraryPage>
                <slot
                  name="fallback"
                  :goTo="goTo"
                  :goBack="goBack"
                  :goHome="goHome"
                  :resetHeight="resetHeight"
                >
                  <div class="DElementLibrary__FallbackContainer">
                    <h2 class="DElementLibrary__FallbackText">
                      This element is currently<br />under construction!
                    </h2>
                    <Button
                      class="DElementLibrary__FallbackButton"
                      @click="goHome"
                      >Go Home</Button
                    >
                  </div>
                </slot>
              </DElementLibraryPage>
            </slot>
          </div>
        </transition-group>
      </Scroll>
    </div>
  </div>
</template>
